		add(g.pipes["affine"], kind+" affine", 1, pc)

		pc = base
		pc.InOff, pc.OutOff, pc.WOff, pc.Aux0 = src, g.hA, alpha, g.aAff
		pc.LDA = uint32(g.lda)
		add(g.pipes["snake"], kind+" snake", groups(g.frames*g.channels, 256), pc)
	}
