package kokoro

import "testing"

func runOnce(t *testing.T, model *Model, asr *Mat, f0, energy, dec []float32) (out []float32, decOut []float32, stages [][]float32) {
	w, _, err := model.Vocoder.Apply(asr, f0, energy, dec)
	if err != nil {
		t.Fatal(err)
	}
	d := model.Vocoder.GPU
	decOut = d.abuf.ReadFloat32At(int(d.aOut), 2*d.run*d.outCh)
	for _, gb := range model.Vocoder.Generator.GPU {
		stages = append(stages, gb.abuf.ReadFloat32At(int(gb.aSum), gb.run*gb.channels))
		_ = gb
	}
	return w, decOut, stages
}

func TestZZBisect(t *testing.T) {
	dev, done := newTestDevice(t)
	defer done()
	m := loadManifest(t)
	model := loadModel(t)
	decStyle, predStyle, _ := model.Style(m.Voice, len([]rune(m.Phonemes)))
	asr := refMat(t, m, "asr", true)
	f0, energy := refCurve(t, m, "f0_pred"), refCurve(t, m, "n_pred")
	frames := asr.Rows

	if err := model.AttachGPU(dev, frames, decStyle, predStyle, DefaultConvKernel); err != nil {
		t.Fatal(err)
	}
	wWav, wDec, wStages := runOnce(t, model, asr, f0, energy, decStyle)
	// the excitation, independent of staging
	wHar := model.Vocoder.Generator.SrcGPU.Harmonic()
	model.DetachGPU()

	ceiling := 2*frames + 13
	if err := model.AttachGPU(dev, ceiling, decStyle, predStyle, DefaultConvKernel); err != nil {
		t.Fatal(err)
	}
	defer model.DetachGPU()
	long := tile(asr, ceiling)
	if _, _, err := model.Vocoder.Apply(long, tileCurve(f0, 2*ceiling), tileCurve(energy, 2*ceiling), decStyle); err != nil {
		t.Fatal(err)
	}
	gWav, gDec, gStages := runOnce(t, model, asr, f0, energy, decStyle)
	gHar := model.Vocoder.Generator.SrcGPU.Harmonic()

	report := func(name string, got, want []float32) {
		if len(got) != len(want) {
			t.Errorf("%s: %d vs %d", name, len(got), len(want))
			return
		}
		bad, first := 0, -1
		for i := range got {
			if got[i] != want[i] {
				bad++
				if first < 0 {
					first = i
				}
			}
		}
		d := compare(t, got, want)
		t.Logf("%-10s %6d/%d differ, first at %d, relative %.3g", name, bad, len(got), first, d.Rel())
	}
	report("harmonic", gHar.Data, wHar.Data)
	report("decoder", gDec, wDec)
	for i := range gStages {
		report("stage"+string(rune('0'+i)), gStages[i], wStages[i])
	}
	report("wave", gWav, wWav)
}
